/**
 * @see ./registry.ts for `resolveInstance` / `readInstancesFile`.
 * @see ./probe.ts for `isPortListening` / `isDaemonAlive` / `diagnoseDaemon`.
 * These were migrated out of this file; it re-exports them above and only
 * wires the plugin together.
 */
/**
 * Build the per-connection status cell rc.2's `startConnection` requires.
 *
 * rc.2 takes the writable status cell as an explicit fourth argument instead of
 * creating one per server fiber. Each vectr connection gets its own cell so
 * concurrent agent and codebase connections never overwrite one another's
 * status; contained observer failures go to the plugin logger.
 *
 * @param ctx - plugin context whose logger receives observer failures.
 * @param label - connection label included in the diagnostic prefix.
 * @returns a fresh writable status cell for one connection.
 */
function createConnectionStatusCell(ctx: Context, label: string): McpStatusCell {
  return new McpStatusCell((message, error) => ctx.logger.warn(`vectr-client(${label}): ${message}`, error))
}

/**
 * Transport-closure budget handed to `startConnection`, matching rc.2's
 * `DEFAULT_CLOSE_TIMEOUT_MS` (the `mcp-client` schema default). Vectr has no
 * config knob for it; the value must stay finite because rc.2 rejects a
 * missing budget at the type level.
 */
const MCP_CLOSE_TIMEOUT_MS = 5_000

/**
 * Install the vectr MCP connection for one agent. Re-reads the registry on
 * every call so a daemon restart (new port / new pid) is picked up by the next
 * `agent/created` or seed without a Host reload.
 * @param ctx - plugin context (the loader fiber) providing agents and logger.
 * @param handles - live connection handles keyed by agent.
 * @param promptFibers - live system-prompt injection fibers keyed by agent.
 * @param instancesPath - absolute path of the vectr daemon registry.
 * @param config - resolved plugin configuration.
 * @param agent - the agent whose workspace resolves the daemon port.
 */
export function install(
  ctx: Context,
  handles: Map<Agent, ConnectionHandle>,
  promptFibers: Map<Agent, Fiber>,
  instancesPath: string,
  config: Required<Config>,
  agent: Agent,
  codebasesPath?: string,
  /** Agents disposed while their liveness probe is still in flight (see P1 in
   * `apply`). When set, the IIFE tears down the freshly-created connection /
   * prompt fiber instead of leaking it to host teardown. Defaults to an empty
   * set so callers that do not seed live agents (unit tests) need not pass it. */
  disposed: WeakSet<Agent> = new WeakSet<Agent>(),
  codebaseBoundAgents: WeakSet<Agent> = new WeakSet<Agent>(),
  codebaseHandles?: Map<Agent, ConnectionHandle[]>,
  /** Dynamic working-memory injection; omitted by unit tests that only exercise prompt sections. */
  injector?: HostInjector,
): void {
  // Guard against already-disposed agents immediately at the function entry
  if (disposed.has(agent)) return

  // Completely decouple prompt injection from daemon connection retry.
  // Prompt injection is guarded solely by !promptFibers.has(agent).
  // Connection establishment is guarded solely by entry !== undefined && !handles.has(agent).
  // If both prompt guidance and main connection are already established, early return.
  // CRITICAL: NEVER early return merely because promptFibers exists, or a failed initial probe
  // will permanently prevent retry / reconnection!
  if (handles.has(agent) && promptFibers.has(agent)) return
  const cwd = agent.session.header.cwd
  if (cwd === undefined) {
    // A session without a workspace cwd cannot be bound to any vectr daemon.
    // Falling back to process.cwd() would silently bind the agent to the wrong
    // workspace's daemon (or none), so we skip explicitly instead.
    ctx.logger.warn(`vectr-client: no cwd on session ${agent.id}, skipping vectr binding`)
    return
  }
  // Re-read the registry on every call (D-7): a daemon restart that rewrote
  // the registry (new port / new pid) is picked up without a Host reload.
  let instances: InstancesFile | undefined
  try {
    instances = readInstancesFile(ctx, instancesPath)
  } catch (error) {
    // An unparseable registry must not veto agent/created publication: skip
    // this agent with a diagnostic instead of throwing into the listener.
    ctx.logger.warn(`vectr-client: cannot read daemon registry at ${instancesPath} (${String(error)}); skipping bind for session ${agent.id}`)
  }

  let codebases: CodebaseEntry[] | undefined
  if (codebasesPath !== undefined) {
    try {
      codebases = loadCodebases(codebasesPath)
    } catch (error) {
      ctx.logger.warn(`vectr-client: cannot read codebase metadata at ${codebasesPath} (${String(error)}); skipping codebase binds for session ${agent.id}`)
    }
  }

  const entry = instances !== undefined ? resolveInstance(instances, cwd) : undefined
  if (entry !== undefined && !isValidInstanceEntry(entry)) {
    ctx.logger.warn(
      `vectr-client: invalid instance entry for session ${agent.id} (cwd=${cwd}): ${JSON.stringify(entry)}, skipping connection`,
    )
  }
  const validEntry = entry !== undefined && isValidInstanceEntry(entry) ? entry : undefined
  if (!hasCodebase({ workspace: cwd, entry: validEntry, codebases })) {
    ctx.logger.info(`vectr-client: no vectr daemon for ${cwd}, skipping`)
    return
  }

  // Working-memory doctrine ships for every bound daemon: memory is orthogonal
  // to code indexing, so memory-only workspaces must still get it. Only the
  // code retrieval negative constraint and the grep shadow depend on an
  // indexed codebase, where vectr can actually replace grep.
  const hasCode = hasIndexedCodebase({ workspace: cwd, entry: validEntry, codebases })
  const serverName = config.serverName || DEFAULT_SERVER_NAME
  if (!promptFibers.has(agent)) {
    const fiber = agent.ctx.inject(['systemPrompt'], (scope) => {
      scope.systemPrompt.section({
        name: VECTR_MEMORY_SECTION_NAME,
        order: VECTR_MEMORY_SECTION_ORDER,
        text: getVectrMemoryText(),
      })
      if (!hasCode) return
      scope.systemPrompt.section({
        name: VECTR_GUIDANCE_SECTION_NAME,
        order: VECTR_GUIDANCE_SECTION_ORDER,
        text: getVectrGuidanceText(serverName),
      })
      scope.systemPrompt.section({
        name: VECTR_GREP_SECTION_NAME,
        order: scope.systemPrompt.getSectionOrder?.('TOOL_GREP') ?? VECTR_GREP_SECTION_ORDER,
        text: getVectrGrepText(serverName),
      })
    })
    if (disposed.has(agent)) {
      void fiber.dispose().catch(() => {})
    } else {
      promptFibers.set(agent, fiber)
    }
  }

  // Main workspace connection establishment with de-vetoing and reconnect resilience:
  // Aligned with installCodebaseConnections:
  // 1. Guard with isValidInstanceEntry(entry). Invalid entry logs a warning and skips connection.
  // 2. Concurrency debounced synchronously via !handles.has(agent).
  // 3. Isolated with try-catch so synchronous startup exceptions never crash agent/created.
  // 4. Background advisory telemetry via diagnoseDaemon logs slow response/not alive warnings,
  //    strictly forbidding abort or vetoing the connection handle.
  if (validEntry !== undefined && !handles.has(agent)) {
    try {
      const host = validEntry.host ?? DEFAULT_HOST
      const port = validEntry.port
      injector?.bind(agent, { host, port, hasCode })
      const policy = resolveReconnectPolicy(config.reconnect, `vectr-client(${config.serverName}): reconnect`)
      // The SCOPED agent context routes every registration into that agent's
      // tool layer; disposal of the scope (which the loop runs BEFORE emitting
      // `agent/disposed`) unwinds the tools, so this listener only closes the
      // HTTP connection.
      const conn = startConnection(agent.ctx, {
        transport: 'streamable-http',
        serverName: config.serverName,
        url: `http://${host}:${port}/mcp`,
        headers: {},
        toolCallTimeoutMs: config.toolCallTimeoutMs,
        closeTimeoutMs: MCP_CLOSE_TIMEOUT_MS,
        expandTemplates: false,
        failOnStartupError: false,
      }, policy, createConnectionStatusCell(ctx, `session ${agent.id}`))

      void conn.ready.then((outcome) => {
        if (outcome.error !== undefined) {
          // D-1: route the failure to the agent-visible channel when one is bound
          // to the session, so the agent/user (not only the loader fiber) sees it.
          // The message always carries cwd/port/error so it is self-diagnosing.
          const message = `vectr-client: vectr connection failed for session ${agent.id} (cwd=${cwd}, port=${port}): ${String(outcome.error)}`
          if (agent.ctx?.logger !== undefined) agent.ctx.logger.warn(message)
          else ctx.logger.warn(message)
        }
      })

      // P1: register the connection. If the agent was disposed during the connection
      // window, tear the connection down immediately.
      if (disposed.has(agent)) {
        void conn.dispose().catch(() => {})
      } else {
        handles.set(agent, conn)
      }
    } catch (error) {
      ctx.logger.warn(
        `vectr-client: failed to initialize main connection for session ${agent.id} (cwd=${cwd}): ${String(error)}`,
      )
    }

    // Background advisory telemetry probe (non-blocking, non-vetoing):
    // Runs independently to diagnose and log warnings (e.g. slow response, hung process, port closed),
    // but NEVER aborts or disposes the connection handle, allowing MCP reconnect policy to self-heal.
    void (async () => {
      try {
        const diagnosis = await diagnoseDaemon(validEntry, {
          httpProbe: (e, ms) => fetchStatus(e, ms),
          httpTimeoutMs: config.daemonHttpTimeoutMs ?? DEFAULT_DAEMON_HTTP_TIMEOUT_MS,
          tcpTimeoutMs: config.daemonTcpTimeoutMs ?? DEFAULT_DAEMON_TCP_TIMEOUT_MS,
        })
        if (!diagnosis.alive) {
          const pid = validEntry.pid === undefined ? 'n/a' : String(validEntry.pid)
          const reason = diagnosis.reason ?? 'HTTP_PROBE_UNREACHABLE'
          ctx.logger.warn(
            `vectr-client: vectr daemon not alive, advisory telemetry warning for session ${agent.id} (cwd=${cwd}, workspace=${validEntry.workspace}, port=${validEntry.port}, pid=${pid}, reason=${reason})`,
          )
        }
      } catch (err) {
        ctx.logger.warn(`vectr-client: daemon probe error for session ${agent.id}: ${String(err)}`)
      }
    })()
  }

  // Feature B: also bind every persisted codebase whose status is 'up'. These
  // are host-level MCP servers (each with a globally-unique serverName), so a
  // failed bind must not veto the agent and only logs a warning. Runs once per
  // agent.
  if (codebasesPath !== undefined && !codebaseBoundAgents.has(agent)) {
    codebaseBoundAgents.add(agent)
    // The main connection above — established when this session's cwd resolved to
    // a live daemon — already serves that daemon's tools. Pass its endpoint down so
    // the codebase loop does not bind the entry that mirrors it under a
    // `vectr_<hash>_<slug>` prefix: two registrations of one daemon endpoint mean
    // two byte-identical tool schemas in every request.
    const mainEndpoint = validEntry !== undefined ? mcpEndpointKey(validEntry.host, validEntry.port) : undefined
    void installCodebaseConnections(ctx, config, agent, codebasesPath, instances, cwd, disposed, codebaseHandles, mainEndpoint)
  }
}

/**
 * Bind-address aliases that all terminate at the loopback interface. `InstanceEntry.host`
 * is the daemon BIND address (see codebases.ts A1: a codebase entry's `host` is the SSH
 * target and never matches it), while a codebase bind always dials
 * `http://127.0.0.1:<localPort>/mcp` — so the two sides must be compared after this
 * normalization, otherwise a daemon registered as `0.0.0.0`/`localhost` would be bound twice.
 */
const LOCAL_BIND_ALIASES = new Set(['127.0.0.1', 'localhost', '::1', '[::1]', '0.0.0.0', '::'])

/**
 * Identity of a vectr daemon endpoint (`host:port`) as it is actually dialled.
 *
 * The endpoint is what determines the tool schema an MCP registration produces, so it
 * is the dedupe key for bindings. The owning workspace is not: one workspace may own
 * several daemons (that is the multi-codebase feature), while a codebase entry can
 * mirror the very daemon the main connection already serves.
 * @param host - host as recorded for the connection; undefined means DEFAULT_HOST.
 * @param port - TCP port of the daemon endpoint.
 * @returns the normalized `host:port` key.
 */
export function mcpEndpointKey(host: string | undefined, port: number): string {
  const recorded = (host ?? DEFAULT_HOST).trim().toLowerCase()
  const dialHost = LOCAL_BIND_ALIASES.has(recorded) ? DEFAULT_HOST : recorded
  return `${dialHost}:${port}`
}

/**
 * Explain why a codebase entry must NOT be bound because it would duplicate a
 * registration that already exists (the main connection, or one made earlier in the
 * same pass). Returns undefined when the bind should proceed.
 * @param entry - candidate codebase entry.
 * @param endpoint - normalized endpoint of that entry.
 * @param mainServerName - `config.serverName` of the main connection.
 * @param mainEndpoint - endpoint the main connection already serves, when it is being established.
 * @param boundEndpoints - endpoints already bound by this pass.
 * @returns the reason to skip, or undefined to bind.
 */
function duplicateBindReason(
  entry: CodebaseEntry,
  endpoint: string,
  mainServerName: string,
  mainEndpoint: string | undefined,
  boundEndpoints: ReadonlySet<string>,
): string | undefined {
  if (entry.serverName === mainServerName) {
    return `server name collides with the main "${mainServerName}" registration`
  }
  if (mainEndpoint !== undefined && endpoint === mainEndpoint) {
    return `endpoint ${endpoint} is already served by the main "${mainServerName}" connection`
  }
  if (boundEndpoints.has(endpoint)) {
    return `endpoint ${endpoint} is already bound by another codebase entry`
  }
  return undefined
}

/**
 * Connect the agent to every persisted codebase entry with `status === 'up'`.
 * Each entry exposes a Streamable HTTP MCP endpoint at
 * `http://127.0.0.1:<localPort>/mcp`; registration uses the entry's
 * `serverName` (globally unique). A bind failure only logs a warning and never
 * blocks the main workspace connection.
 * @param ctx - plugin context providing the logger.
 * @param config - resolved plugin configuration.
 * @param agent - the agent to bind the codebase tools to.
 * @param codebasesPath - absolute path of the codebase metadata file.
 * @param mainEndpoint - normalized `host:port` of the daemon the main
 *   `config.serverName` connection is being bound to for this agent; a codebase
 *   entry that resolves to the same endpoint is skipped instead of registering
 *   the same tools a second time. Undefined when no main connection covers it.
 */
export async function installCodebaseConnections(
  ctx: Context,
  config: Required<Config>,
  agent: Agent,
  codebasesPath: string,
  instances?: InstancesFile,
  cwd?: string,
  disposed: WeakSet<Agent> = new WeakSet<Agent>(),
  codebaseHandles?: Map<Agent, ConnectionHandle[]>,
  mainEndpoint?: string,
): Promise<void> {
  // Guard against already-disposed agents immediately at function entry
  if (disposed.has(agent)) return

  let entries: CodebaseEntry[]
  try {
    entries = loadCodebases(codebasesPath)
  } catch (error) {
    ctx.logger.warn(`vectr-client: cannot read codebase metadata at ${codebasesPath} (${String(error)}); skipping codebase binds for session ${agent.id}`)
    return
  }
  // Per-workspace binding isolation (阶段1): only bind codebases owned by the
  // agent's resolved workspace. `ws` comes from the agent cwd; when `cwd` or the
  // registry is absent we fall back to binding all 'up' entries (the architect's
  // `ws === undefined || e.workspace === ws` clause) — a permissive default used
  // only when isolation data is unavailable.
  // B4: resolve the agent's own workspace from its cwd via the registry. When
  // that is unavailable (session has no cwd, or no registry), do NOT blindly
  // bind every 'up' entry — that would bind UNASSIGNED/orphaned entries to an
  // agent. Only bind entries whose OWN workspace is a known key in the registry;
  // with no registry at all this binds nothing (the safe default). The risk this
  // accepts: an entry whose daemon has since vanished from the registry is also
  // skipped (it cannot be isolated), which is preferable to over-binding.
  const agentWs = (cwd !== undefined && instances !== undefined)
    ? resolveInstance(instances, cwd)?.workspace
    : undefined
  const knownWorkspaces = new Set(Object.values(instances ?? {}).map((e) => e.workspace))
  const policy = resolveReconnectPolicy(config.reconnect, 'vectr-client(codebase): reconnect')
  // Endpoints bound by this pass, so two entries that resolve to the same daemon
  // do not register the same tools twice.
  const boundEndpoints = new Set<string>()
  for (const entry of entries) {
    if (disposed.has(agent)) return
    if (entry.status !== 'up' || entry.localPort === undefined) continue
    if (agentWs !== undefined) {
      if (entry.workspace !== agentWs) continue
    } else if (entry.workspace === undefined || !knownWorkspaces.has(entry.workspace)) {
      continue
    }
    // The bind below always dials 127.0.0.1:<localPort>, so the entry's endpoint is
    // keyed from that — and compared with the main connection's endpoint. This is the
    // fix for the current workspace's OWN entry being bound a second time: the main
    // `config.serverName` connection already serves that daemon, and binding the
    // mirror entry adds a second identical tool schema (≈23 tools) per request.
    // An entry in the same workspace that serves a DIFFERENT daemon still binds.
    const endpoint = mcpEndpointKey(DEFAULT_HOST, entry.localPort)
    const duplicate = duplicateBindReason(entry, endpoint, config.serverName, mainEndpoint, boundEndpoints)
    if (duplicate !== undefined) {
      ctx.logger.info(`vectr-client: skipping codebase bind ${entry.serverName} for session ${agent.id}: ${duplicate}`)
      continue
    }
    boundEndpoints.add(endpoint)
    try {
      const conn = startConnection(agent.ctx, {
        transport: 'streamable-http',
        serverName: entry.serverName,
        url: `http://127.0.0.1:${entry.localPort}/mcp`,
        headers: {},
        toolCallTimeoutMs: config.toolCallTimeoutMs,
        closeTimeoutMs: MCP_CLOSE_TIMEOUT_MS,
        expandTemplates: false,
        failOnStartupError: false,
      }, policy, createConnectionStatusCell(ctx, `codebase ${entry.serverName}`))
      void conn.ready.then((outcome) => {
        if (outcome.error !== undefined) {
          const message = `vectr-client: codebase connection failed for session ${agent.id} (serverName=${entry.serverName}, port=${entry.localPort}): ${String(outcome.error)}`
          if (agent.ctx?.logger !== undefined) agent.ctx.logger.warn(message)
          else ctx.logger.warn(message)
        }
      })
      if (disposed.has(agent)) {
        void conn.dispose().catch(() => {})
      } else if (codebaseHandles !== undefined) {
        let list = codebaseHandles.get(agent)
        if (list === undefined) {
          list = []
          codebaseHandles.set(agent, list)
        }
        list.push(conn)
      }
    } catch (error) {
      ctx.logger.warn(`vectr-client: codebase bind threw for ${entry.serverName} (session ${agent.id}): ${String(error)}`)
    }
  }
}

/**
 * What the daemon registry actually says about ONE local codebase entry's port.
 * - `reconcile`          — the registry has a daemon for the directory this entry
 *                          serves and the entry does not point at it: stale metadata.
 * - `own-port-registered` — the entry's own port is one the registry already
 *                          lists for that directory: nothing is stale, the owning
 *                          workspace simply has more than one daemon.
 * - `no-truth`           — no registry view applies (unreadable registry, an entry
 *                          that names no directory, or no record for it).
 */
export type LocalRegistryTruth =
  | { readonly kind: 'reconcile'; readonly port: number }
  | { readonly kind: 'own-port-registered'; readonly port: number }
  | { readonly kind: 'no-truth' }

/**
 * Ports the daemon registry attributes to one directory.
 *
 * A record's stored `workspace` is the directory that daemon serves — the `--path`
 * it was started with — so this asks "which ports serve THIS directory", not "which
 * ports belong to the owning workspace a codebase entry is filed under".
 *
 * `resolveInstanceExact` answers "which daemon serves this workspace" with a
 * SINGLE record, because vectr keys `instances.json` by `sha256(cwd)[:12]`. The
 * file can still describe several daemons of one workspace: records under
 * foreign keys whose stored `workspace` is equal (trailing-slash tolerant) are
 * precisely the shape `resolveInstanceExact`'s own fallback exists to honor.
 * Reconciling against only the first of them would collapse the workspace into
 * one daemon. Matching is the same exact-string rule, never the prefix match of
 * `resolveInstance` (that one hands every record-less codebase the enclosing
 * `/home/csy` daemon's port).
 */
export function workspaceDaemonPorts(instances: InstancesFile, workspace: string): number[] {
  const wanted = workspace.endsWith('/') ? workspace.slice(0, -1) : workspace
  const ports: number[] = []
  for (const record of Object.values(instances)) {
    if (typeof record?.port !== 'number' || typeof record?.workspace !== 'string') continue
    const stored = record.workspace.endsWith('/') ? record.workspace.slice(0, -1) : record.workspace
    if (stored === wanted) ports.push(record.port)
  }
  return ports
}

/**
 * Registry truth for ONE local codebase entry, as consumed by
 * {@link healLocalCodebase}'s `recordedPort` parameter.
 *
 * The lookup used to be keyed by workspace alone: `instances[workspace].port`,
 * which is fine while a workspace has one daemon and destructive when it has
 * more. A codebase entry created for a SECOND daemon of that workspace records
 * that daemon's own port, and a workspace-only lookup reports the primary
 * record instead — so heal declared the entry stale, rewrote `localPort` and
 * PERSISTED the rewrite into `vectr-codebases.json`. Several daemons of one
 * workspace silently collapsed into one, with the user's metadata rewritten to
 * match.
 *
 * The lookup is keyed on {@link daemonDirectoryOf} instead — the directory the
 * daemon actually serves, which is what the registry keys its records by — and the
 * entry is declared stale only when its own port is NOT one the registry already
 * lists for that directory. When it is, the entry agrees with the registry about a
 * live daemon and there is nothing to fix: `own-port-registered` is returned, no
 * lookup is handed to heal, and the metadata stays untouched. A stale or dead port
 * (not listed for the directory) still reconciles to the primary record exactly as
 * before, which is the behavior the original defect-fix needed: a recorded port
 * answering for a DIFFERENT directory is a port another daemon is squatting, and a
 * TCP/HTTP probe cannot tell that apart — see the `RecordedPortLookup` contract
 * in `codebases.ts`.
 */
export function localRegistryTruth(
  instances: InstancesFile | undefined,
  entry: Pick<CodebaseEntry, 'workspace' | 'path' | 'localPort'>,
): LocalRegistryTruth {
  if (instances === undefined) return { kind: 'no-truth' }
  const served = daemonDirectoryOf(entry)
  if (served === undefined || served === '') return { kind: 'no-truth' }
  if (typeof entry.localPort === 'number' && workspaceDaemonPorts(instances, served).includes(entry.localPort)) {
    return { kind: 'own-port-registered', port: entry.localPort }
  }
  const primary = resolveInstanceExact(instances, served)
  if (typeof primary?.port !== 'number') return { kind: 'no-truth' }
  return { kind: 'reconcile', port: primary.port }
}

/**
 * Run the startup heal across all eligible codebases in the metadata registry.
 * Local codebases are processed strictly sequentially (`for ... of` with `await`),
 * so that projects don't all storm the local port allocator concurrently at boot.
 * Remote codebase tunnels continue to be kicked off in the background.
 */
export async function startupHeal(
  deps: CodebaseDeps,
  codebasesPath: string,
  instancesPath: string,
  ctx: Context,
  config: Required<Config>,
): Promise<void> {
  const now = Date.now()
  // Exact-match registry view, read once. It must be `resolveInstanceExact`,
  // never `resolveInstance`: the latter's prefix match would hand every
  // record-less codebase the enclosing `/home/csy` daemon's port and silently
  // bind it to the wrong workspace's index. The per-entry verdict comes from
  // {@link localRegistryTruth}, which also refuses to declare an entry stale
  // when its own port is already a registered daemon of the directory that entry
  // serves.
  let startupInstances: InstancesFile | undefined
  try {
    startupInstances = readInstancesFile(ctx, instancesPath)
  } catch (error) {
    ctx.logger.warn(`vectr-client: cannot read daemon registry at ${instancesPath} (${String(error)}); local codebase ports will not be reconciled`)
  }
  const probe = daemonAliveProbe(ctx, config)
  for (const entry of loadCodebases(codebasesPath)) {
    if (!startupHealEligible(entry)) continue
    // Cooldown: skip if we already attempted this slug too recently. The
    // timestamp is kept in-process; it does not survive a restart, which is
    // fine — a fresh process starts with a clean slate and one attempt.
    const lastAttempt = startupHealCooldown.get(entry.slug)
    if (lastAttempt !== undefined && now - lastAttempt < STARTUP_HEAL_COOLDOWN_MS) continue
    startupHealCooldown.set(entry.slug, now)
    if (entry.type === 'remote') {
      void ensureTunnelUp(deps, codebasesPath, entry).catch((err) => {
        ctx.logger.warn(`vectr-client: could not re-establish tunnel for ${entry.slug}: ${String(err)}`)
      })
    } else {
      // Local daemon: a host restart SIGTERMs every daemon in this service's
      // cgroup and nothing used to start them again. Heal reconciles the
      // metadata port against the daemon registry first (only when the registry
      // shows the recorded port is NOT a daemon of the directory this entry
      // serves), then probes, so a live daemon — including a second daemon of
      // the same owning workspace — and the sessions using its port are never
      // disturbed.
      // Sequential await prevents port allocation collisions on startup.
      try {
        const truth = localRegistryTruth(startupInstances, entry)
        if (truth.kind === 'own-port-registered') {
          ctx.logger.info(
            `vectr-client: local codebase ${entry.slug} keeps its own port ${truth.port}; `
            + `the daemon registry already lists a daemon serving `
            + `${daemonDirectoryOf(entry) ?? entry.slug} on it`,
          )
        }
        const result = await healLocalCodebase(
          deps,
          codebasesPath,
          entry,
          probe,
          truth.kind === 'reconcile' ? () => truth.port : undefined,
        )
        if (result === 'reconciled') {
          ctx.logger.info(`vectr-client: corrected stale port for local codebase ${entry.slug} from the daemon registry`)
        }
        if (result === 'started') {
          ctx.logger.info(`vectr-client: restarted local vectr daemon for ${entry.slug}`)
        }
      } catch (err) {
        ctx.logger.warn(`vectr-client: could not restart local vectr daemon for ${entry.slug}: ${String(err)}`)
      }
    }
  }
}

/**
 * Turn a mode harvest into log output (boot path: {@link apply}). Split out of
 * the boot sequence so the diagnostics — the part an operator actually needs
 * when a remembered mode and the live registry disagree — are testable without
 * booting the plugin, and so a store that could not be written is never
 * indistinguishable from a store that had nothing to write.
 * @param logger - host logger (production: `ctx.logger`).
 * @param modesPath - the store path, named in every message so a warn is actionable.
 * @param harvest - the {@link ModeHarvestResult} from {@link harvestFromInstances}.
 */
export function reportModeHarvest(
  logger: { info: (message: string) => void; warn: (message: string) => void },
  modesPath: string,
  harvest: ModeHarvestResult,
): void {
  for (const conflict of harvest.conflicts) {
    logger.warn(
      `vectr-client: mode store conflict for ${conflict.workspace} in ${modesPath}: `
      + `registry says ${conflict.incoming}, store says ${conflict.stored}; keeping ${conflict.stored} `
      + `(harvest never overwrites a remembered mode). Set the mode explicitly if the registry is right.`,
    )
  }
  if (harvest.writeFailed) {
    logger.warn(
      `vectr-client: mode store write FAILED for ${modesPath}: ${harvest.added.length} harvested `
      + `mode(s) were not persisted; the next start may bring these workspaces up in a different mode.`,
    )
    return
  }
  if (harvest.added.length > 0) {
    logger.info(
      `vectr-client: mode store recorded ${harvest.added.length} workspace mode(s) from the daemon registry in ${modesPath}`,
    )
  }
}

/**
 * The vectr-client plugin entry: seed already-live agents, watch
 * `agent/created` / `agent/disposed`, and close every connection on teardown.
 * @param ctx - plugin context whose fiber owns the listeners and handles.
 * @param config - resolved plugin configuration.
 */
export function apply(ctx: Context, config: Config = {}): void {
  const resolved: Required<Config> = {
    instancesPath: config.instancesPath ?? DEFAULT_INSTANCES_FILE,
    serverName: config.serverName ?? DEFAULT_SERVER_NAME,
    toolCallTimeoutMs: config.toolCallTimeoutMs ?? DEFAULT_TOOL_CALL_TIMEOUT_MS,
    reconnect: {
      enabled: config.reconnect?.enabled ?? true,
      initialDelayMs: config.reconnect?.initialDelayMs ?? 500,
      maxDelayMs: config.reconnect?.maxDelayMs ?? 30_000,
      maxAttempts: config.reconnect?.maxAttempts ?? 10,
    },
    codebasesPath: config.codebasesPath ?? DEFAULT_CODEBASES_FILE,
    secretsPath: config.secretsPath ?? DEFAULT_SECRETS_FILE,
    modesPath: (() => {
      const p = config.modesPath ?? DEFAULT_MODES_FILE
      return isAbsolute(p) ? p : resolve(process.cwd(), p)
    })(),
    daemonHttpTimeoutMs: config.daemonHttpTimeoutMs ?? DEFAULT_DAEMON_HTTP_TIMEOUT_MS,
    daemonTcpTimeoutMs: config.daemonTcpTimeoutMs ?? DEFAULT_DAEMON_TCP_TIMEOUT_MS,
    cliPath: config.cliPath ?? '',
    cliTimeoutMs: config.cliTimeoutMs ?? DEFAULT_CLI_TIMEOUT_MS,
    recallTimeoutMs: config.recallTimeoutMs ?? DEFAULT_RECALL_TIMEOUT_MS,
    upgradeTimeoutMs: (() => {
      const envVal = process.env.VECTR_UPGRADE_TIMEOUT_MS ? parseInt(process.env.VECTR_UPGRADE_TIMEOUT_MS.trim(), 10) : undefined
      if (typeof envVal === 'number' && !isNaN(envVal) && envVal > 0) return envVal
      return config.upgradeTimeoutMs ?? DEFAULT_UPGRADE_TIMEOUT_MS
    })(),
    autoStartDaemons: config.autoStartDaemons ?? true,
    bootRecallTimeoutMs: config.bootRecallTimeoutMs ?? 1500,
    promptRecallTimeoutMs: config.promptRecallTimeoutMs ?? DEFAULT_PROMPT_RECALL_TIMEOUT_MS,
    toolRecallTimeoutMs: config.toolRecallTimeoutMs ?? 300,
    promptRecallLimit: config.promptRecallLimit ?? 3,
    perTurnTokenCap: config.perTurnTokenCap ?? 500,
    perSessionTokenCap: config.perSessionTokenCap ?? 8000,
    maxInjectionChars: config.maxInjectionChars ?? 4000,
    injectCompactionSnapshot: config.injectCompactionSnapshot ?? true,
  }
  // Relative-path fallback (P3-safe): only resolves against process.cwd()
  // when Config supplies a *relative* path. Both defaults
  // (DEFAULT_INSTANCES_FILE / DEFAULT_CODEBASES_FILE) are absolute
  // (homedir-based), so the common case never uses process.cwd() as a
  // workspace fallback (D-4 still skips sessions lacking a cwd).
  const instancesPath = isAbsolute(resolved.instancesPath)
    ? resolved.instancesPath
    : resolve(process.cwd(), resolved.instancesPath)
  const codebasesPath = isAbsolute(resolved.codebasesPath)
    ? resolved.codebasesPath
    : resolve(process.cwd(), resolved.codebasesPath)
  // P6: best-effort cleanup of stale tunnel control sockets from a crashed
  // prior process before we (re)establish live tunnels. (a) Narrow the scan
  // to OUR codebases' slug prefixes so a host restart with a different pid
  // does not touch unrelated plugins/users sharing tmpdir.
  try {
    const startupSlugs = loadCodebases(codebasesPath)
      .filter((e) => e.type === 'remote' && typeof e.slug === 'string')
      .map((e) => e.slug)
    cleanupStaleTunnelSockets(undefined, startupSlugs)
  } catch {
    // best-effort startup hygiene; never fatal.
  }
  // 阶段1: idempotently backfill `workspace` + recompute the composite
  // `serverName` on existing meta (no-op once migrated). A2: skip entirely when
  // no registry is present (writing would poison the sticky UNASSIGNED field).
  // Best-effort — a malformed registry must not block host startup.
  try {
    const instances = readInstancesFile(ctx, instancesPath)
    if (instances !== undefined) migrateCodebases(codebasesPath, instances, ctx.logger)
  } catch (err) {
    ctx.logger.warn(`vectr-client: startup codebase migration skipped: ${String(err)}`)
  }
  // 问题1B: bring every persisted 'up' remote tunnel back up at startup. A
  // tunnel can die while the host stays up (ssh master crash, network blip); the
  // meta keeps `status: 'up'` but the endpoint is unreachable. Re-probe and
  // reopen each here (fire-and-forget, bounded by ssh's quick return) so the
  // endpoint comes back without blocking host startup. Each entry heals
  // independently so one failure cannot block the others. `apply` is sync in the
  // host contract, so this runs concurrently rather than awaited.
  //
  // (b) Heal-scope fix: a tunnel persisted as `status: 'error'` (or `'down'`)
  // was a permanent deadlock — the user-facing route surfaced the diagnostic
  // but no automatic recovery was ever attempted. Widen the predicate to also
  // include 'down' and 'error' entries (legacy 'up' behavior preserved),
  // gated by a per-slug cooldown so a persistently-unreachable host is not
  // hammered on every host restart.
  //
  // LOCAL daemons get the same treatment through `healLocalCodebase`: dsh runs
  // inside `deepseek-harness.service`, so a host restart SIGTERMs every daemon
  // in that cgroup (KillMode=control-group) while `~/.vectr/instances.json` and
  // this metadata keep the dead pid/`up` status. Before this, nothing ever
  // started them again and every workspace showed "daemon offline" forever.
  // `vectr start` is called without `--port` so vectr reuses the port the dead
  // registry entry still records — the already-published MCP URL survives.
  //
  // MODE HARVEST (must stay strictly ahead of the heal and of the start-all
  // sweep below): `mode` in `instances.json` is runtime state — a dead record is
  // pruned, and BOTH `vectr start` and `vectr status` prune dead records
  // globally. So the user's mode choice has to be copied into the plugin's own
  // store before the first spawn of this boot, or the spawn it triggers erases
  // it and the workspace returns as a full re-index.
  try {
    const harvest = harvestFromInstances(resolved.modesPath, readInstancesFile(ctx, instancesPath))
    reportModeHarvest(ctx.logger, resolved.modesPath, harvest)
  } catch (err) {
    ctx.logger.warn(`vectr-client: mode store harvest skipped: ${String(err)}`)
  }
  try {
    const deps = buildCodebaseDeps(ctx, resolved.secretsPath, resolved.modesPath)
    void startupHeal(deps, codebasesPath, instancesPath, ctx, resolved).catch((err) => {
      ctx.logger.warn(`vectr-client: startup heal failed: ${String(err)}`)
    })
  } catch (err) {
    ctx.logger.warn(`vectr-client: startup codebase heal skipped: ${String(err)}`)
  }
  // Auto-start every known workspace's daemon (registry ∪ DSH discovery) once
  // per host boot. Fire-and-forget: `apply` is sync in the host contract, the
  // sweep is serialized behind the same local-daemon lock as every other start,
  // and neither its latency nor a rejection may reach `apply`.
  if (resolved.autoStartDaemons) {
    void withLocalDaemonLock(() => startAllDaemons(buildStartAllDeps(ctx, instancesPath, resolved), {}))
      .then((sweep) => {
        ctx.logger.info(
          `vectr-client: auto-start daemons: ${sweep.started} started, ${sweep.alreadyRunning} already running, ${sweep.failed} failed`,
        )
      })
      .catch((err) => {
        ctx.logger.warn(`vectr-client: auto-start daemons failed: ${String(err)}`)
      })
  }
  const handles = new Map<Agent, ConnectionHandle>()
  const codebaseHandles = new Map<Agent, ConnectionHandle[]>()
  // Per-agent system-prompt injection fibers (feature A-2): the guidance
  // section is contributed only when the daemon is verified alive, and disposed
  // together with the agent. Keyed separately from `handles` because the fiber
  // opens a dependency scope rather than an MCP connection.
  const promptFibers = new Map<Agent, Fiber>()
  // P1: agents disposed during their liveness-probe window. The IIFE in install
  // registers the fiber/connection only after the await; if the agent is torn
  // down before then, the disposed handler finds nothing in the maps. This set
  // lets the IIFE detect that and dispose the freshly-created registration.
  // WeakSet eliminates strong reference accumulation for discarded Agent objects.
  const disposed = new WeakSet<Agent>()
  const codebaseBoundAgents = new WeakSet<Agent>()

  // Dynamic working-memory injection (boot / prompt / tool / compaction).
  // Static doctrine stays in the system prompt; every per-turn pack is a
  // pre-step user message so it is assembled after it was fetched.
  const injectionConfig: InjectionConfig = {
    bootRecallTimeoutMs: resolved.bootRecallTimeoutMs,
    promptRecallTimeoutMs: resolved.promptRecallTimeoutMs,
    toolRecallTimeoutMs: resolved.toolRecallTimeoutMs,
    promptRecallLimit: resolved.promptRecallLimit,
    perTurnTokenCap: resolved.perTurnTokenCap,
    perSessionTokenCap: resolved.perSessionTokenCap,
    maxInjectionChars: resolved.maxInjectionChars,
    injectCompactionSnapshot: resolved.injectCompactionSnapshot,
  }
  const injector = new HostInjector({ logger: ctx.logger, config: injectionConfig })
  ctx.on('agent/pre-step', (payload, next) => injector.onPreStep(payload, next), { prepend: true })
  ctx.on('agent/disposed', ({ agent }) => { injector.dispose(agent) })
  ctx.on('session/event', (session, event) => { injector.onSessionEvent(session, event) })
  // Tool-anchored gotcha injection. Minimal test doubles for apply() omit
  // `inject`, so attach only when the host exposes the dependency scope.
  if (typeof ctx.inject === 'function') {
    ctx.inject(['tools'], (scope) => {
      scope.on('tools/post-execute', (exec, _result, next) => injector.onPostExecute(exec, next))
    })
  }

  // The registry is read inside install() on every call (D-7), so seed and
  // each agent/created both see the current on-disk state. The codebase
  // metadata path is passed so install also binds up codebases.
  // Ordering matters: install() binds the injector endpoint, then the session
  // source decides whether the boot recall must be re-delivered, and only
  // then is the boot prefetch issued.
  for (const agent of ctx.agents.list()) {
    install(ctx, handles, promptFibers, instancesPath, resolved, agent, codebasesPath, disposed, codebaseBoundAgents, codebaseHandles, injector)
    injector.markSource(agent, 'startup')
    injector.prefetchBoot(agent)
  }
  ctx.on('agent/created', ({ agent, source }) => {
    install(ctx, handles, promptFibers, instancesPath, resolved, agent, codebasesPath, disposed, codebaseBoundAgents, codebaseHandles, injector)
    injector.markSource(agent, source)
    injector.prefetchBoot(agent)
    return undefined
  })
  ctx.on('agent/disposed', ({ agent }) => {
    disposed.add(agent)
    codebaseBoundAgents.delete(agent)
    void handles.get(agent)?.dispose()
    handles.delete(agent)

    const list = codebaseHandles.get(agent)
    if (list !== undefined) {
      for (const conn of list) void conn.dispose().catch(() => {})
      codebaseHandles.delete(agent)
    }

    const fiber = promptFibers.get(agent)
    if (fiber !== undefined) {
      void fiber.dispose().catch((error: unknown) => {
        // A failed prompt-fiber disposal must not veto the rest of agent
        // teardown; log and continue (same posture as the connection dispose).
        ctx.logger.warn(`vectr-client: prompt-section cleanup failed for ${agent.id}: ${error instanceof Error ? error.message : String(error)}`)
      })
      promptFibers.delete(agent)
    }
  })
  ctx.effect(() => async () => {
    for (const conn of handles.values()) void conn.dispose()
    handles.clear()
    for (const list of codebaseHandles.values()) {
      for (const conn of list) void conn.dispose().catch(() => {})
    }
    codebaseHandles.clear()
    for (const fiber of promptFibers.values()) void fiber.dispose().catch(() => {})
    promptFibers.clear()
    // Kill any surviving ssh tunnels recorded in the codebase metadata so a
    // host teardown does not leave orphaned port-forward processes.
    //
    // First pass: per recorded entry, prefer the recorded control-socket
    // exit (works even when tunnelPid was never recorded), then best-effort
    // SIGTERM the recorded PID. If NEITHER could reach the master (no
    // tunnelCtl, ssh missing, pid recycled), queue the entry for the slug-
    // prefix fallback so the host teardown does not leak an orphan master
    // when the host pid has changed.
    let fallbackNeeded: CodebaseEntry[] = []
    try {
      for (const entry of loadCodebases(codebasesPath)) {
        if (entry.type !== 'remote') continue
        const hasRecorded = entry.tunnelPid !== undefined || entry.tunnelCtl !== undefined
        if (!hasRecorded) continue
        let recordedOk = false
        if (entry.tunnelCtl !== undefined && entry.host !== undefined) {
          // Capture narrowed values before the closure (property narrowing
          // does not flow into the Promise executor callback).
          const ctl = entry.tunnelCtl
          const host = entry.host
          try {
            // F2: the old fire-and-forget `spawn` marked teardown ok before
            // ssh had even started, and an async 'error' event (missing ssh
            // binary) was unhandled and could crash the host teardown. Await
            // the exit and only count a clean exit (code 0, no signal) as ok;
            // otherwise the slug-prefix fallback sweep below takes over.
            const result = await new Promise<{ code: number; signal: NodeJS.Signals | null }>((resolveExit) => {
              const child = spawn('ssh', ['-O', 'exit', '-S', ctl, host])
              child.on('error', () => { resolveExit({ code: 1, signal: null }) })
              child.on('close', (code, signal) => { resolveExit({ code: code ?? 1, signal }) })
            })
            recordedOk = result.code === 0 && result.signal === null
          } catch {
            // best-effort: control-socket exit unavailable at teardown.
          }
        }
        if (entry.tunnelPid !== undefined) {
          // N3: best-effort kill only — it never marks the teardown ok. The
          // recorded pid may be stale/recycled while a surviving master still
          // holds its socket, so `recordedOk` stays driven by the control-
          // socket exit above and the slug sweep below still runs.
          try {
            process.kill(entry.tunnelPid, 'SIGTERM')
          } catch (err) {
            // ESRCH = tunnel already gone (normal case, ignore); EPERM = pid
            // belongs to another user (warn; also not ok).
            const code = (err as NodeJS.ErrnoException).code
            if (code !== 'ESRCH') {
              ctx.logger.warn(`vectr-client: teardown cannot SIGTERM recorded tunnelPid ${entry.tunnelPid}: ${String(err)}`)
            }
          }
        }
        // (a) Recorded teardown could not reach the master -> sweep tmpdir
        // for any /tmp/vectr-tunnel-<slug>-*.sock the entry left behind.
        if (!recordedOk) fallbackNeeded.push(entry)
      }
    } catch {
      // metadata unreadable; nothing to clean up.
    }
    // Second pass: slug-prefix fallback for the orphans the recorded path
    // could not reach. Uses the existing ssh runner via deps so the
    // password is injected (mirrors deleteCodebase's fallback path).
    if (fallbackNeeded.length > 0) {
      try {
        const teardownDeps = buildCodebaseDeps(ctx, resolved.secretsPath, resolved.modesPath)
        await cleanupOrphanedTunnelsForCodebases(teardownDeps, fallbackNeeded)
      } catch {
        // best-effort; teardown must never throw out of the disposer.
      }
    }
  }, 'vectr-client.connections')

  // Feature A (C1): host-side JSON routes backing the workspace console.
  // Registered in the root plugin scope (not per-agent) so a single pair of
  // management endpoints serves every workspace; disposed with this fiber.
  registerManagementRoutes(ctx, instancesPath, resolved)
  registerCodebaseRoutes(ctx, codebasesPath, resolved.secretsPath, instancesPath, resolved)

  // 4-Layer architecture: wire Domain, Infra, and Bridge services for session management
  const instanceResolver = new InstanceResolver(instancesPath, ctx)
  const apiClient = new VectrApiClient()
  const codebaseService = new CodebaseService(codebasesPath)
  const cliRunner = new VectrCliRunner({
    cliPath: resolved.cliPath || undefined,
    timeoutMs: resolved.cliTimeoutMs,
  })
  const sessionService = new SessionVectrService({
    instanceResolver,
    apiClient,
    codebaseService,
    cliRunner,
    statusTimeoutMs: resolved.daemonHttpTimeoutMs,
    recallTimeoutMs: resolved.recallTimeoutMs,
    upgradeTimeoutMs: resolved.upgradeTimeoutMs,
    modesPath: resolved.modesPath,
    warn: message => ctx.logger.warn(message),
  })
  registerSessionRoutes(ctx, sessionService)
}

/**
 * Write a JSON body with the given status code.
 * @param res - the node:http response.
 * @param statusCode - HTTP status to send.
 * @param body - value serialized as JSON.
 */
function sendJson(res: ServerResponse, statusCode: number, body: unknown): void {
  const payload = JSON.stringify(body)
  res.writeHead(statusCode, { 'content-type': 'application/json; charset=utf-8' })
  res.end(payload)
}

/**
 * Read a JSON request body with a size cap (defense against unbounded reads).
 * @param req - the incoming request.
 * @param limitBytes - maximum accepted bytes.
 * @returns the parsed body, or a thrown Error on over-length / bad JSON.
 */
async function readJsonBody(req: IncomingMessage, limitBytes = 1_000_000): Promise<unknown> {
  const chunks: Buffer[] = []
  let total = 0
  for await (const chunk of req) {
    total += chunk.length
    if (total > limitBytes) throw new Error('request body too large')
    chunks.push(chunk as Buffer)
  }
  if (chunks.length === 0) return {}
  const text = Buffer.concat(chunks).toString('utf8')
  return JSON.parse(text)
}

/**
 * Register the workspace-console HTTP routes on the injected webServer:
 *
 * - `GET /api/vectr/workspaces` → {@link scanWorkspaces} result (JSON array of
 *   {@link WorkspaceView}).
 * - `POST /api/vectr/trigger-index` body `{ "port": number }` (or
 *   `{ "workspace": string }`) → resolve the single matching registry entry and
 *   call {@link triggerIndex}; returns the {@link TriggerResult}.
 * - `POST /api/vectr/daemons/start-all` / `POST /api/vectr/daemons/start` body
 *   `{ "workspace": string }` → start the dead daemons of every registered
 *   workspace / the daemon of one workspace ({@link startDaemonForWorkspace}).
 *
 * Both handlers are Cordis effects (the disposer from `webServer.register`),
 * so they vanish with the plugin fiber. A registry read failure on either
 * route answers 500 with the diagnostic rather than crashing the request.
 *
 * @param ctx - plugin context carrying the webServer service.
 * @param instancesPath - absolute path of `instances.json`.
 * @param config - resolved plugin configuration (supplies `daemonHttpTimeoutMs`).
 */
/** Outcome of one workspace inside a {@link StartAllResponse}. */
export interface StartAllEntryResult {
  /** Absolute workspace path as recorded in `instances.json`. */
  workspace: string
  /** Daemon port, or `null` when no port could be established. */
  port: number | null
  /** `started` = spawned and re-probed live; `already-running` = no spawn; `failed`. */
  status: 'started' | 'already-running' | 'failed'
  /** Real failure text; present only when `status === 'failed'`. */
  error?: string
}

/** Response body of `POST /api/vectr/daemons/start-all`. */
export interface StartAllResponse {
  /** `true` only when no entry failed. */
  ok: boolean
  started: number
  alreadyRunning: number
  failed: number
  results: StartAllEntryResult[]
}

/**
 * Injected seams for {@link startAllDaemons}. Production wires the real registry
 * reader, probe layer and CLI runner in {@link buildStartAllDeps}; tests inject
 * fakes so the handler runs unmodified with no socket and no child process.
 */
export interface StartAllDeps {
  /** Registry reader (production: {@link readInstancesFile}). */
  readInstances: () => InstancesFile | undefined
  /** Bounded liveness probe (production: {@link diagnoseDaemon}). */
  probe: (entry: InstanceEntry) => Promise<AliveDiagnosis>
  /** Daemon spawn (production: {@link VectrCliRunner.start}). */
  start: (options: VectrStartOptions) => Promise<StartResult>
  /**
   * DSH's own workspace list (production: {@link discoverWorkspaceRoots} over
   * {@link DEFAULT_DSH_WORKSPACE_FILE}). The sweep unions it with the registry
   * so a workspace whose daemon was never started is still started here.
   */
  discover: () => DiscoveredWorkspace[]
  /** Optional warn sink for a non-fatal event (a throwing `discover`); absent in tests. */
  warn?: (message: string) => void
  /**
   * Mode remembered by the plugin for a workspace path (production: the mode
   * store, src/modes.ts). Absent in tests and for direct use: without it the
   * sweep reads the mode off the registry exactly as before.
   */
  modeLookup?: (workspace: string) => PersistedMode | undefined
  /**
   * Persist the mode an explicit request chose for a workspace the sweep just
   * started, so the choice survives the next prune + restart. Optional: absent
   * in tests unless the spec is about mode persistence.
   */
  recordMode?: (workspace: string, mode: PersistedMode) => void
}

/**
 * Start the vectr daemon for every known workspace — registry entries plus
 * `deps.discover()` entries that have no registry record — strictly one at a
 * time (deterministic order: registry by port ascending then workspace path,
 * then discovered-only by path ascending — `instances.json` is keyed by sha256
 * hash, so its own key order carries no meaning). Sequential by construction:
 * concurrent `vectr start` runs race on free-port discovery and on the
 * lock-guarded `instances.json` write.
 *
 * A workspace whose daemon already answers the probe is reported
 * `already-running` and is NOT spawned again (a second daemon would fight the
 * first over the same registry port). A spawn is followed by exactly ONE
 * bounded re-probe of the (possibly rewritten) registry record; an endpoint
 * that never answers is reported `failed`, never `started`. A discovered-only
 * workspace whose directory is gone is `failed` (`no such workspace
 * directory:`), never skipped — a known workspace must not read as "nothing to
 * do".
 *
 * A per-workspace failure is recorded in `results[].error`, counted in `failed`,
 * and forces `ok:false` — the sweep never reports success over a failed spawn.
 * A throwing `deps.discover()` is the one exception: it degrades to an empty
 * discovery list (reported through `deps.warn`) and the registry sweep carries
 * on.
 *
 * @param deps - registry/probe/spawn/discovery seams (see {@link StartAllDeps}).
 * @param body - parsed JSON request body; `{ memoryOnly?: boolean }` is honored.
 * @returns the aggregated {@link StartAllResponse}.
 */
export async function startAllDaemons(deps: StartAllDeps, body: unknown): Promise<StartAllResponse> {
  const requested = (body as { memoryOnly?: unknown } | null)?.memoryOnly
  const forcedMemoryOnly = typeof requested === 'boolean' ? requested : undefined

  // The registry only knows daemons started at least once; DSH's own workspace
  // list is what makes this the whole known set. Discovery is decoration, never
  // a blocker: a throwing source degrades to an empty list (warn, no failure).
  let discovered: DiscoveredWorkspace[] = []
  try {
    discovered = deps.discover()
  } catch (error) {
    deps.warn?.(`vectr-client: workspace discovery failed: ${String(error)}`)
  }

  const raw = Object.values(deps.readInstances() ?? {})
  const valid = raw.filter(isValidInstanceEntry)
  const sorted = valid.sort((a, b) => a.port - b.port || a.workspace.localeCompare(b.workspace))
  const results: StartAllEntryResult[] = []

  // What is remembered is the mode this sweep ACTUALLY applied, for a workspace this
  // sweep has just PROVEN to be up in that mode (`started.ok && after.alive`), so a
  // failed spawn cannot leave a mode behind for the next boot to replay. It is not
  // limited to a mode the request body named: a mode only the daemon registry knew
  // (a hand-run `vectr restart --memory-only`) would otherwise never reach the
  // store, and `prune_dead()` deletes the whole registry record the moment the
  // process is gone — the next boot would then know nothing, emit no flag and
  // rebuild a memory-only workspace as a full re-index. The write is skipped when
  // the store already says exactly what was applied (no pointless disk writes).
  // Recording a `full` is a statement of fact, not a request: `full` still emits no
  // flag at all (see {@link modeStartFlags} / `VectrCliRunner.start`).
  const rememberAppliedMode = (
    workspace: string,
    applied: PersistedMode,
    remembered: PersistedMode | undefined,
    knownFromRegistry: PersistedMode | undefined,
  ): void => {
    // An explicit request-body boolean that contradicts the mode this plugin would
    // otherwise have inferred is said out loud, with the source named. The explicit
    // request still wins (precedence is unchanged); the warn exists because
    // promoting a memory-only workspace to `full` is the expensive direction, and
    // it used to happen in silence whenever the mode came from the registry and the
    // store had no record yet.
    // Saying it out loud is independent of writing it: an override that happens to
    // need no disk write is still an override the user should see.
    if (forcedMemoryOnly !== undefined) {
      const prior = knownFromRegistry ?? remembered
      if (prior !== undefined && prior !== applied) {
        deps.warn?.(knownFromRegistry !== undefined
          ? `vectr-client: explicit ${applied} mode overrides the daemon registry's ${prior} mode for ${workspace}`
            + (remembered === undefined ? ' (the mode store has no record for this workspace yet)' : '')
          : `vectr-client: explicit ${applied} mode overrides the remembered ${prior} mode for ${workspace}`)
      }
    }
    if (remembered === applied) return
    deps.recordMode?.(workspace, applied)
  }

  for (const entry of sorted) {
    // Mode precedence: an explicit request-body boolean -> the mode recorded on
    // this registry entry -> the mode the plugin remembered for this workspace.
    // No mode is invented: a workspace with no record anywhere is started with
    // `vectr start`'s own default (no mode flag), exactly as before.
    const remembered = deps.modeLookup?.(normalizeWorkspacePath(entry.workspace))
    const mode = resolveStartMode({
      forcedMemoryOnly,
      registryMode: entry.mode,
      storedMode: remembered,
    })
    const extraRoots = entry.extra_roots

    try {
      const before = await deps.probe(entry)
      if (before.alive) {
        results.push({ workspace: entry.workspace, port: entry.port, status: 'already-running' })
        continue
      }

      // The applied mode is remembered FURTHER DOWN, only after this spawn is
      // proven alive. Recording it here — before `deps.start` — is the defect
      // this replaces: `{ memoryOnly: false }` against a store holding
      // `memory_only` wrote `full`, the daemon never came up, and the next boot
      // read `full` out of the store, emitted no flag, and re-indexed a workspace
      // the user had deliberately downgraded.
      const started = await deps.start({
        workspace: entry.workspace,
        memoryOnly: mode === 'memory_only',
        ...(mode === 'search_only' ? { searchOnly: true } : {}),
        ...(extraRoots !== undefined && extraRoots.length > 0 ? { extraRoots } : {}),
      })
      if (!started.ok) {
        results.push({
          workspace: entry.workspace,
          port: null,
          status: 'failed',
          error: started.error ?? `vectr start failed: ${started.stderr ?? 'no diagnostic'}`,
        })
        continue
      }

      // Re-probe the registry once: a successful `vectr start` may have moved
      // the daemon to a different free port, so the pre-start record is stale.
      const refreshed = resolveInstanceExact(deps.readInstances() ?? {}, entry.workspace) ?? entry
      const after = await deps.probe(refreshed)
      // Success is `started.ok && after.alive` — the spawn returned ok AND the
      // daemon answers the post-start probe. "Did not throw" is not success, and a
      // mode remembered from a spawn that never came up is worse than no mode at
      // all: it decides the next boot.
      if (after.alive) rememberAppliedMode(entry.workspace, mode, remembered, toPersistedMode(entry.mode))
      results.push(after.alive
        ? { workspace: entry.workspace, port: refreshed.port, status: 'started' }
        : {
            workspace: entry.workspace,
            port: refreshed.port ?? null,
            status: 'failed',
            error: `daemon did not answer the post-start probe (${after.reason ?? 'no reason reported'})`,
          })
    } catch (error) {
      results.push({ workspace: entry.workspace, port: null, status: 'failed', error: String(error) })
    }
  }

  // Malformed registry records are surfaced as failures, not dropped: a
  // workspace this sweep cannot even describe must not read as "nothing to do".
  for (const entry of raw.filter(e => !isValidInstanceEntry(e))) {
    results.push({
      workspace: typeof (entry as { workspace?: unknown }).workspace === 'string'
        ? String((entry as { workspace?: unknown }).workspace)
        : '(invalid registry entry)',
      port: null,
      status: 'failed',
      error: 'invalid registry entry: missing a non-empty workspace and a valid port',
    })
  }

  // Discovery-only candidates, appended after every registry entry (registry
  // wins a path clash so its recorded port is preserved) and sorted by path so
  // the tail is deterministic.
  const known = new Set(valid.map(entry => normalizeWorkspacePath(entry.workspace)))
  // Recorded `mode` per normalized workspace path, read from *every* registry
  // record — including the malformed records reported above, which are the
  // reason this map is not just the valid entries. A stopped daemon or a record
  // whose port went stale still carries the mode the user chose, and a
  // workspace in that situation lands here rather than in the registry sweep.
  // Dropping the mode is how a memory-only workspace came back as full.
  const recordedModes = new Map<string, string>()
  for (const entry of raw) {
    const path = (entry as { workspace?: unknown }).workspace
    const mode = (entry as { mode?: unknown }).mode
    if (typeof path !== 'string' || path.trim() === '') continue
    if (typeof mode !== 'string' || mode.trim() === '') continue
    const key = normalizeWorkspacePath(path)
    if (!recordedModes.has(key)) recordedModes.set(key, mode)
  }
  const extras = discovered
    .filter(root => typeof root?.workspace === 'string' && root.workspace.trim() !== '')
    .map(root => normalizeWorkspacePath(root.workspace))
    .filter((workspace) => {
      if (known.has(workspace)) return false
      known.add(workspace)
      return true
    })
    .sort((a, b) => a.localeCompare(b))

  for (const workspace of extras) {
    // Same precedence as the registry sweep: explicit request-body boolean ->
    // mode recorded anywhere in the registry for this path (including a record
    // whose daemon is dead — that is the whole reason `recordedModes` exists) ->
    // the plugin mode store -> nothing remembered, so no flag and `full`.
    const remembered = deps.modeLookup?.(workspace)
    const mode = resolveStartMode({
      forcedMemoryOnly,
      registryMode: recordedModes.get(workspace),
      storedMode: remembered,
    })
    try {
      const stat = statSync(workspace, { throwIfNoEntry: false })
      if (stat === undefined || !stat.isDirectory()) {
        results.push({ workspace, port: null, status: 'failed', error: `no such workspace directory: ${workspace}` })
        continue
      }
    } catch (error) {
      // Unreadable/ENOTDIR paths are reported, never silently skipped.
      results.push({
        workspace,
        port: null,
        status: 'failed',
        error: `no such workspace directory: ${workspace} (${String(error)})`,
      })
      continue
    }

    try {
      const started = await deps.start({
        workspace,
        memoryOnly: mode === 'memory_only',
        ...(mode === 'search_only' ? { searchOnly: true } : {}),
      })
      if (!started.ok) {
        results.push({
          workspace,
          port: null,
          status: 'failed',
          error: started.error ?? `vectr start failed: ${started.stderr ?? 'no diagnostic'}`,
        })
        continue
      }

      const refreshed = resolveInstanceExact(deps.readInstances() ?? {}, workspace)
      if (refreshed === undefined) {
        results.push({
          workspace,
          port: null,
          status: 'failed',
          error: 'daemon started but no registry entry was recorded for the workspace',
        })
        continue
      }
      const after = await deps.probe(refreshed)
      if (after.alive) rememberAppliedMode(workspace, mode, remembered, toPersistedMode(recordedModes.get(workspace)))
      results.push(after.alive
        ? { workspace, port: refreshed.port, status: 'started' }
        : {
            workspace,
            port: refreshed.port,
            status: 'failed',
            error: `daemon did not answer the post-start probe (${after.reason ?? 'no reason reported'})`,
          })
    } catch (error) {
      results.push({ workspace, port: null, status: 'failed', error: String(error) })
    }
  }

  const started = results.filter(r => r.status === 'started').length
  const alreadyRunning = results.filter(r => r.status === 'already-running').length
  const failed = results.filter(r => r.status === 'failed').length
  return { ok: failed === 0, started, alreadyRunning, failed, results }
}

/** Response body of `POST /api/vectr/daemons/start`. */
export interface StartOneResponse {
  ok: boolean
  /** Registry port of the workspace's daemon; present on success and on a 409 "already running". */
  port?: number
  pid?: number
  /** Real failure text; present only when `ok` is false. */
  error?: string
}

/**
 * Start the vectr daemon of a single workspace (`POST /api/vectr/daemons/start`
 * body `{ workspace }`).
 *
 * Shares the spawn/probe path with {@link startAllDaemons} — same injected
 * {@link StartAllDeps}, no second spawner — and returns HTTP-shaped outcomes so
 * the route stays a thin shell:
 *
 * - `400` — no usable `workspace` in the body, a relative path, or a directory
 *   that does not exist (an unknown workspace is a client error).
 * - `409` — a registry record for the workspace is already alive: no spawn, no
 *   port churn, the body carries the live port.
 * - `200` — spawned and re-probed; `{ ok: true, port, pid? }` from the refreshed
 *   registry record (a successful `vectr start` may pick a different free port).
 * - `500` — the spawn failed, no registry entry was recorded, or the daemon never
 *   answered the post-start probe.
 */
export async function startDaemonForWorkspace(
  deps: StartAllDeps,
  body: unknown,
): Promise<{ status: number; body: StartOneResponse }> {
  const requested = (body as { workspace?: unknown } | null | undefined)?.workspace
  if (typeof requested !== 'string' || requested.trim() === '') {
    return { status: 400, body: { ok: false, error: 'workspace must be a non-empty absolute path' } }
  }
  const workspace = requested.trim()
  if (!isAbsolute(workspace)) {
    return { status: 400, body: { ok: false, error: 'workspace must be a non-empty absolute path' } }
  }
  try {
    if (!statSync(workspace).isDirectory()) {
      return { status: 400, body: { ok: false, error: `no such workspace directory: ${workspace}` } }
    }
  } catch (error) {
    // ENOENT/ENOTDIR (and an unreadable parent) all mean "not a workspace we can serve".
    return {
      status: 400,
      body: { ok: false, error: `no such workspace directory: ${workspace} (${String(error)})` },
    }
  }

  try {
    const existing = resolveInstanceExact(deps.readInstances() ?? {}, workspace)
    if (existing !== undefined && (await deps.probe(existing)).alive) {
      // Already running: reported as a conflict, never as a second daemon.
      return {
        status: 409,
        body: { ok: false, error: `daemon already running for ${workspace}`, port: existing.port },
      }
    }

    // Mode precedence, exactly as in the start-all sweep: the live registry
    // record first, then the mode the plugin remembered for this workspace (the
    // record is gone by the time a pruned workspace reaches here), then nothing.
    const mode = resolveStartMode({
      registryMode: existing?.mode,
      storedMode: deps.modeLookup?.(normalizeWorkspacePath(workspace)),
    })
    const started = await deps.start({
      workspace,
      ...(mode === 'memory_only' ? { memoryOnly: true } : {}),
      ...(mode === 'search_only' ? { searchOnly: true } : {}),
    })
    if (!started.ok) {
      return {
        status: 500,
        body: {
          ok: false,
          error: started.error ?? `vectr start failed: ${started.stderr ?? 'no diagnostic'}`,
        },
      }
    }

    const refreshed = resolveInstanceExact(deps.readInstances() ?? {}, workspace)
    if (refreshed === undefined) {
      return {
        status: 500,
        body: { ok: false, error: 'daemon started but no registry entry was recorded for the workspace' },
      }
    }
    const after = await deps.probe(refreshed)
    if (!after.alive) {
      return {
        status: 500,
        body: {
          ok: false,
          error: `daemon did not answer the post-start probe (${after.reason ?? 'no reason reported'})`,
        },
      }
    }
    return {
      status: 200,
      body: { ok: true, port: refreshed.port, ...(refreshed.pid !== undefined ? { pid: refreshed.pid } : {}) },
    }
  } catch (error) {
    return { status: 500, body: { ok: false, error: String(error) } }
  }
}

/**
 * Production workspace discovery: DSH's own registry file, read best-effort.
 * One construction for both consumers (management table + start-all sweep) so
 * the two can never disagree about which workspaces exist.
 */
function defaultWorkspaceDiscovery(ctx: Context): () => DiscoveredWorkspace[] {
  return () => discoverWorkspaceRoots(
    DEFAULT_DSH_WORKSPACE_FILE,
    error => ctx.logger.warn(`vectr-client: workspace discovery failed: ${String(error)}`),
  )
}

/**
 * Build the production {@link StartAllDeps}: the shared registry reader, the
 * shared probe layer with the plugin's configured budgets, and the same
 * {@link VectrCliRunner} the session service uses (one CLI path, one timeout).
 *
 * @param ctx - plugin context (registry read diagnostics).
 * @param instancesPath - absolute path of `instances.json`.
 * @param config - resolved plugin configuration (timeouts + CLI path).
 * @returns the assembled {@link StartAllDeps}.
 */
export function buildStartAllDeps(
  ctx: Context,
  instancesPath: string,
  config: Required<Config>,
): StartAllDeps {
  const cliRunner = new VectrCliRunner({
    cliPath: config.cliPath || undefined,
    timeoutMs: config.cliTimeoutMs,
  })
  const modesPath = config.modesPath ?? DEFAULT_MODES_FILE
  return {
    readInstances: () => readInstancesFile(ctx, instancesPath),
    probe: entry => diagnoseDaemon(entry, {
      httpProbe: fetchStatus,
      httpTimeoutMs: config.daemonHttpTimeoutMs ?? DEFAULT_DAEMON_HTTP_TIMEOUT_MS,
      tcpTimeoutMs: config.daemonTcpTimeoutMs ?? DEFAULT_TCP_TIMEOUT_MS,
    }),
    start: options => cliRunner.start(options),
    discover: defaultWorkspaceDiscovery(ctx),
    warn: message => ctx.logger.warn(message),
    modeLookup: workspace => lookupMode(modesPath, workspace),
    recordMode: (workspace, mode) => {
      if (!writeMode(modesPath, workspace, mode)) {
        ctx.logger.warn(`vectr-client: could not persist ${mode} mode for ${workspace} in ${modesPath}`)
      }
    },
  }
}

export function registerManagementRoutes(
  ctx: Context,
  instancesPath: string,
  config: Required<Config>,
  startAllDeps?: StartAllDeps,
  /**
   * Workspace discovery source for the console table and the start-all sweep
   * (production: DSH's own registry). Injected so tests drive a temp fixture and
   * never read `$HOME`.
   */
  discover: () => DiscoveredWorkspace[] = defaultWorkspaceDiscovery(ctx),
): void {
  // `webServer` is provided by the host; in headless/unit contexts it may be
  // absent. `ctx.get` returns undefined (rather than throwing) so the plugin
  // still loads and the MCP-binding path keeps working without the console
  // routes. The host registration is re-attempted on the next apply only if the
  // service appears, which in practice means a host restart (documented).
  const webServer = ctx.get('webServer')
  if (webServer === undefined) {
    ctx.logger.warn('vectr-client: webServer service unavailable; skipping /api/vectr/* management routes')
    return
  }
  ctx.effect(() => webServer.register({
    kind: 'exact',
    path: '/api/vectr/workspaces',
    handler: async (_req, res) => {
      try {
        const views = await scanWorkspaces(ctx, instancesPath, {
          statusTimeoutMs: config.daemonHttpTimeoutMs,
          discover,
          codebasesPath: config.codebasesPath,
        })
        sendJson(res, 200, views)
      } catch (error) {
        sendJson(res, 500, { error: String(error) })
      }
    },
  }), 'vectr-client: GET /api/vectr/workspaces')

  ctx.effect(() => webServer.register({
    kind: 'exact',
    path: '/api/vectr/trigger-index',
    handler: async (req, res) => {
      if (req.method !== 'POST') {
        sendJson(res, 405, { error: 'method not allowed' })
        return
      }
      let body: unknown
      try {
        body = await readJsonBody(req)
      } catch (error) {
        sendJson(res, 400, { error: String(error) })
        return
      }
      const target = body as { port?: number; workspace?: string }
      const instances = readInstancesFile(ctx, instancesPath)
      if (instances === undefined) {
        sendJson(res, 404, { ok: false, error: 'no vectr daemon registry found' })
        return
      }
      let entry = undefined
      if (typeof target.port === 'number') {
        entry = Object.values(instances).find(e => e.port === target.port)
      } else if (typeof target.workspace === 'string') {
        entry = Object.values(instances).find(e => e.workspace === target.workspace)
      }
      if (entry === undefined) {
        sendJson(res, 404, { ok: false, error: 'no daemon matches the requested port/workspace' })
        return
      }
      // Reuse the shared /v1/status probe (fetchStatus) with the configured
      // timeout so a hung daemon cannot block this route (M2). Same probe the
      // liveness gate uses; never hand-roll fetch here.
      const status = await fetchStatus(entry, config.daemonHttpTimeoutMs ?? DEFAULT_DAEMON_HTTP_TIMEOUT_MS)
      const result = await triggerIndex(entry, status !== undefined ? { status } : {})
      sendJson(res, result.ok ? 200 : 409, result)
    },
  }), 'vectr-client: POST /api/vectr/trigger-index')

  // One-click start-all: POST /api/vectr/daemons/start-all -> start the daemon
  // of every registered or DSH-discovered workspace that is not already
  // answering. Runs under the existing process-wide local-daemon lock
  // (codebases.ts `withLocalDaemonLock`) so this sweep cannot race the codebase
  // manager's own starts on free-port discovery; the sweep itself is sequential
  // (see `startAllDaemons`). The injected `discover` also feeds the built deps:
  // the console table and the sweep must see the same workspace set.
  const deps = startAllDeps ?? { ...buildStartAllDeps(ctx, instancesPath, config), discover }
  ctx.effect(() => webServer.register({
    kind: 'exact',
    path: '/api/vectr/daemons/start-all',
    handler: async (req, res) => {
      if (req.method !== 'POST') {
        sendJson(res, 405, { error: 'method not allowed' })
        return
      }
      let body: unknown
      try {
        body = await readJsonBody(req)
      } catch (error) {
        sendJson(res, 400, { ok: false, error: `Invalid JSON body: ${String(error)}` })
        return
      }
      try {
        sendJson(res, 200, await withLocalDaemonLock(() => startAllDaemons(deps, body)))
      } catch (error) {
        sendJson(res, 500, { ok: false, error: String(error) })
      }
    },
  }), 'vectr-client: POST /api/vectr/daemons/start-all')

  // Per-workspace start: POST /api/vectr/daemons/start body `{ workspace }` ->
  // spawn the daemon of one known workspace, including one discovery listed but
  // that has never run. Same lock and same injected deps as the start-all sweep
  // so a per-workspace start cannot race it on free-port discovery.
  ctx.effect(() => webServer.register({
    kind: 'exact',
    path: '/api/vectr/daemons/start',
    handler: async (req, res) => {
      if (req.method !== 'POST') {
        sendJson(res, 405, { error: 'method not allowed' })
        return
      }
      let body: unknown
      try {
        body = await readJsonBody(req)
      } catch (error) {
        sendJson(res, 400, { ok: false, error: `Invalid JSON body: ${String(error)}` })
        return
      }
      try {
        const result = await withLocalDaemonLock(() => startDaemonForWorkspace(deps, body))
        sendJson(res, result.status, result.body)
      } catch (error) {
        sendJson(res, 500, { ok: false, error: String(error) })
      }
    },
  }), 'vectr-client: POST /api/vectr/daemons/start')
}

/**
 * Build the runtime dependencies for the codebase manager from the host
 * environment. `spawnRunner` wraps `node:child_process spawn`; `sshRunner`
 * wraps `spawn('ssh', args)` and, for password-auth codebases, injects the
 * password via `sshpass` (`-o PreferredAuthentications=password`); `credStore` prefers the host `credentials`
 * service (when present) and otherwise falls back to a file-backed store.
 *
 * When the host `credentials` service exists, its async `set`/`unset` are
 * adapted to the sync-friendly {@link CredentialStore} shape by awaiting; `get`
 * resolves via `resolve(ref)`. Ref names follow `VECTR_SSH_<SLUG>`.
 *
 * @param ctx - plugin context (for `credentials` lookup + logger).
 * @param secretsPath - fallback secret file path.
 * @param modesPath - plugin mode store path; when given, every start path in
 *   `codebases.ts` (startup heal, local-daemon restart, codebase create) emits
 *   the mode the user chose. Omitted -> no `modeLookup` -> no mode flag, i.e.
 *   the pre-L2 behaviour, which is what the existing specs assert.
 * @returns the assembled {@link CodebaseDeps}-compatible runners + store.
 */
export function buildCodebaseDeps(
  ctx: Context,
  secretsPath: string,
  modesPath?: string,
): {
    spawnRunner: SpawnRunner
    sshRunner: SshRunner
    credStore: CredentialStore
    warn: (message: string) => void
    modeLookup?: (dir: string) => PersistedMode | undefined
  } {
  const spawnRunner: SpawnRunner = (command, args) => {
    const child = spawn(command, args, { stdio: ['ignore', 'pipe', 'pipe'] })
    let stdout = ''
    let stderr = ''
    child.stdout?.on('data', (d: Buffer) => { stdout += d.toString() })
    child.stderr?.on('data', (d: Buffer) => { stderr += d.toString() })
    const promise = new Promise<{ code: number; stdout: string; stderr: string; signal: NodeJS.Signals | null }>((resolveExit) => {
      child.on('error', (err) => { resolveExit({ code: 1, stdout, stderr: `${stderr}\n${String(err)}`, signal: null }) })
      // F2: capture the signal so success gating can distinguish a clean exit
      // from a kill (a signaled "exit" is not a success).
      child.on('close', (code, signal) => { resolveExit({ code: code ?? 1, stdout, stderr, signal }) })
    })
    return {
      promise,
      kill() {
        child.kill('SIGTERM')
      },
    } satisfies SpawnHandle
  }
  const sshRunner: SshRunner = (args, auth) => {
    if (auth?.password !== undefined) {
      // Password-auth hosts: feed the password to sshpass via a 0600 temp file
      // (`-f`) so the plaintext never lands in argv (visible in `ps` /proc) or
      // the process environment. The file is unlinked once the ssh process has
      // exited (success or failure); the file is written before spawn so sshpass
      // can read it at startup. Key-auth hosts (auth absent) run plain `ssh`.
      const passFile = join(tmpdir(), `vectr-sshpass-${process.pid}-${randomBytes(6).toString('hex')}`)
      writeFileSync(passFile, auth.password, { mode: 0o600 })
      try {
        const handle = spawnRunner('sshpass', ['-f', passFile, 'ssh',
          '-o', 'PreferredAuthentications=password', '-o', 'PubkeyAuthentication=no', ...args])
        void handle.promise.finally(() => {
          try { rmSync(passFile) } catch {
            // best-effort cleanup; a stale 0600 temp file only holds a password.
          }
        })
        return handle
      } catch (err) {
        // spawnRunner threw synchronously (illegal cwd/option, ENOENT, …) before
        // any child existed, so the `finally` above never registered. The temp
        // file already holds the plaintext password, so remove it now instead of
        // leaking a 0600 secret into /tmp, then propagate the original error.
        try { rmSync(passFile) } catch {
          // best-effort; nothing more we can do here.
        }
        throw err
      }
    }
    return spawnRunner('ssh', args)
  }

  const hostCreds = ctx.get('credentials') as
    | { set: (ref: string, v: string) => Promise<void>; unset: (ref: string) => Promise<void>; resolve: (ref: string) => Promise<{ value: string } | undefined> }
    | undefined
  let credStore: CredentialStore
  if (hostCreds !== undefined) {
    credStore = {
      set: (ref, value) => hostCreds.set(ref, value),
      get: (ref) => hostCreds.resolve(ref).then((r) => r?.value),
      unset: (ref) => hostCreds.unset(ref),
    }
  } else {
    credStore = new FileCredentialStore(secretsPath)
  }

  return {
    spawnRunner,
    sshRunner,
    credStore,
    // (c) warn sink: findFreePort's preferred-port-migration warning surfaces
    // in the host log instead of being silently swallowed inside the module.
    warn: (message: string) => {
      ctx.logger?.warn?.(message)
    },
    // Mode persistence: keyed on the daemon directory, the same key
    // `startLocalDaemon` derives. No store path -> no lookup -> no mode flag.
    ...(modesPath !== undefined
      ? { modeLookup: (dir: string) => lookupMode(modesPath, dir) }
      : {}),
  }
}

/**
 * Extract the codebase slug from a request pathname. Strips the codebase route
 * prefix and keeps only the first path segment, so `/api/vectr/codebases/demo`
 * and `/api/vectr/codebases/demo/test` both yield `demo` — the `/test` suffix is
 * an action, not part of the slug. This was the root cause of
 * `POST /api/vectr/codebases/:slug/test` returning 404: the slug was derived as
 * `demo/test` and never matched a persisted entry (改动3).
 * @param pathname - request pathname (e.g. `/api/vectr/codebases/demo/test`).
 * @returns the bare slug, or `''` when the pathname carries no slug segment.
 */
export function slugFromPathname(pathname: string): string {
  // C3 asked to drop `?? ''`, but this repo enables `noUncheckedIndexedAccess`,
  // so `String.split(...)[0]` is typed `string | undefined`; the coalesce is
  // load-bearing (an empty array access must resolve to `''`), not redundant.
  return decodeURIComponent(pathname.replace('/api/vectr/codebases/', '')).split('/')[0] ?? ''
}

/**
 * Register the feature-B codebase management HTTP routes:
 *
 * - `GET  /api/vectr/codebases` → list persisted entries (no secrets).
 * - `POST /api/vectr/codebases` body {@link CodebaseSpec} → create (password
 *   only forwarded to the store; never echoed in the response).
 * - `DELETE /api/vectr/codebases/:slug` → delete.
 * - `POST /api/vectr/codebases/:slug/test` → liveness probe.
 *
 * The routes are Cordis effects so they vanish with the plugin fiber. A host
 * without `webServer` skips them (logged once).
 *
 * @param ctx - plugin context carrying `webServer` + `credentials`.
 * @param codebasesPath - absolute path of the codebase metadata file.
 * @param secretsPath - fallback secret file path.
 * @param instancesPath - instances JSON file path.
 * @param config - optional configuration override (e.g. daemonHttpTimeoutMs).
 */
export function registerCodebaseRoutes(
  ctx: Context,
  codebasesPath: string,
  secretsPath: string,
  instancesPath: string = DEFAULT_INSTANCES_FILE,
  config?: { daemonHttpTimeoutMs?: number; modesPath?: string },
): void {
  const webServer = ctx.get('webServer')
  if (webServer === undefined) {
    ctx.logger.warn('vectr-client: webServer service unavailable; skipping /api/vectr/codebases* routes')
    return
  }
  const deps = buildCodebaseDeps(ctx, secretsPath, config?.modesPath)
  const httpTimeoutMs = config?.daemonHttpTimeoutMs ?? DEFAULT_HTTP_TIMEOUT_MS
  const modesPath = config?.modesPath

  /**
   * Mode the `/start` route must ask `vectr start` for. The route body carries no
   * explicit mode, so this is a read-only precedence chain (registry record →
   * persisted mode store → default `full`) and never writes the mode store: a
   * plain start must not silently promote or demote a workspace's recorded mode.
   */
  const startModeFlags = (workspace: string): string[] => {
    if (modesPath === undefined) return []
    let registryMode: string | undefined
    try {
      const wanted = normalizeWorkspacePath(workspace)
      for (const inst of Object.values(readInstancesFile(ctx, instancesPath) ?? {})) {
        if (inst?.workspace && normalizeWorkspacePath(inst.workspace) === wanted) {
          registryMode = inst.mode
          break
        }
      }
    } catch {
      // Registry unreadable: fall back to the persisted mode store.
    }
    return modeStartFlags(resolveStartMode({ registryMode, storedMode: lookupMode(modesPath, workspace) }))
  }

  ctx.effect(() => webServer.register({
    kind: 'exact',
    path: '/api/vectr/codebases',
    handler: async (req, res) => {
      if (req.method === 'GET') {
        try {
          const url = new URL(req.url ?? '', 'http://localhost')
          const wsFilter = url.searchParams.get('workspace') ?? undefined
          let list = loadCodebases(codebasesPath).map(stripSecret)
          // 阶段1: optional `?workspace=` scoping for the workspace console.
          if (wsFilter !== undefined) {
            list = list.filter(e => e.workspace === wsFilter)
          }

          // Prepend Primary codebase for non-memory_only workspaces that have mounted codebases
          let instances: InstancesFile | undefined
          try {
            instances = readInstancesFile(ctx, instancesPath)
          } catch {
            // ignore
          }
          if (wsFilter !== undefined) {
            const inst = instances ? resolveInstance(instances, wsFilter) : undefined
            const isMemoryOnly = inst ? (inst.mode === 'memory_only' || inst.mode === 'memory-only') : false
            if (!isMemoryOnly && list.length > 0 && !list.some(e => e.isPrimary || isSystemPrimarySlug(e.slug))) {
              const isListening = inst?.port ? await isPortListening(inst.host ?? '127.0.0.1', inst.port, 300) : false
              list = [
                {
                  id: `primary:${wsFilter}`,
                  slug: 'primary',
                  type: 'local',
                  path: wsFilter,
                  workspace: wsFilter,
                  serverName: `primary_${wsFilter}`,
                  status: isListening ? 'up' : 'down',
                  isPrimary: true,
                },
                ...list,
              ]
            }
          } else {
            const workspacesWithEntries = new Set<string>()
            for (const item of list) {
              if (item.workspace && item.workspace !== UNASSIGNED_WORKSPACE) {
                workspacesWithEntries.add(item.workspace)
              }
            }
            const primaries: typeof list = []
            for (const ws of workspacesWithEntries) {
              const inst = instances ? resolveInstance(instances, ws) : undefined
              const isMemoryOnly = inst ? (inst.mode === 'memory_only' || inst.mode === 'memory-only') : false
              const alreadyHasPrimary = list.some(
                e => e.workspace === ws && (e.isPrimary || isSystemPrimarySlug(e.slug)),
              )
              if (!isMemoryOnly && !alreadyHasPrimary) {
                const wsKey = createHash('sha256').update(ws).digest('hex').slice(0, WORKSPACE_KEY_LENGTH)
                // Multi-workspace global listing: avoid pushing identical slug 'primary'
                const slug = workspacesWithEntries.size > 1 ? `primary-${wsKey}` : 'primary'
                const isListening = inst?.port ? await isPortListening(inst.host ?? '127.0.0.1', inst.port, 300) : false
                primaries.push({
                  id: `primary:${ws}`,
                  slug,
                  type: 'local',
                  path: ws,
                  workspace: ws,
                  serverName: `primary_${wsKey}`,
                  status: isListening ? 'up' : 'down',
                  isPrimary: true,
                })
              }
            }
            if (primaries.length > 0) {
              list = [...primaries, ...list]
            }
          }

          sendJson(res, 200, list)
        } catch (error) {
          sendJson(res, 500, { error: String(error) })
        }
        return
      }
      if (req.method === 'POST') {
        let body: unknown
        try {
          body = await readJsonBody(req)
        } catch (error) {
          sendJson(res, 400, { error: String(error) })
          return
        }
        const spec = body as CodebaseSpec
        if (spec && typeof spec === 'object') {
          const rawPath = spec.path || (spec as unknown as { remotePath?: string }).remotePath
          if (rawPath && typeof rawPath === 'string') {
            spec.path = rawPath.trim()
          }
          if (!spec.auth && spec.password) {
            spec.auth = 'password'
          }
        }
        try {
          const entry = await createCodebase(deps, codebasesPath, spec)
          sendJson(res, 201, stripSecret(entry))
        } catch (error) {
          sendJson(res, 400, { error: String(error) })
        }
        return
      }
      sendJson(res, 405, { error: 'method not allowed' })
    },
  }), 'vectr-client: /api/vectr/codebases')

  ctx.effect(() => webServer.register({
    kind: 'prefix',
    path: '/api/vectr/codebases',
    handler: async (req, res) => {
      const url = new URL(req.url ?? '', 'http://localhost')
      const slug = slugFromPathname(url.pathname)
      if (slug.length === 0) {
        sendJson(res, 400, { error: 'missing codebase slug' })
        return
      }
      const normSlug = slug.trim().toLowerCase()
      const list = () => loadCodebases(codebasesPath)
      const find = () => list().find(e => e.slug.trim().toLowerCase() === normSlug)

      if (req.method === 'DELETE') {
        if (isSystemPrimarySlug(normSlug)) {
          sendJson(res, 403, { ok: false, error: 'Cannot delete primary codebase of the workspace' })
          return
        }
        const entry = find()
        if (entry === undefined) {
          sendJson(res, 404, { ok: false, error: 'no such codebase' })
          return
        }
        const isPrimaryByPath = Boolean(
          entry.workspace && entry.path && resolve(entry.path) === resolve(entry.workspace),
        )
        const isPrimaryBySlug =
          typeof entry.slug === 'string' && isSystemPrimarySlug(entry.slug)
        if (entry.isPrimary || isPrimaryBySlug || isPrimaryByPath) {
          sendJson(res, 403, { ok: false, error: 'Cannot delete primary codebase of the workspace' })
          return
        }
        try {
          await deleteCodebase(deps, codebasesPath, entry)
          sendJson(res, 200, { ok: true })
        } catch (error) {
          sendJson(res, 500, { ok: false, error: String(error) })
        }
        return
      }
      if (req.method === 'POST' && url.pathname.endsWith('/test')) {
        if (isSystemPrimarySlug(normSlug)) {
          let instances: InstancesFile | undefined
          try {
            instances = readInstancesFile(ctx, instancesPath)
          } catch {
            // ignore
          }
          if (!instances) {
            sendJson(res, 503, { ok: false, error: 'Instance registry unavailable' })
            return
          }
          let targetWs = url.searchParams.get('workspace') ?? undefined
          if (!targetWs && isSystemPrimarySlug(normSlug) && normSlug !== 'primary') {
            const key = normSlug.replace(/^primary-/i, '')
            for (const [k, inst] of Object.entries(instances)) {
              if (
                k.startsWith(key) ||
                key.startsWith(k) ||
                (inst?.workspace && createHash('sha256').update(inst.workspace).digest('hex').startsWith(key))
              ) {
                targetWs = inst?.workspace
                break
              }
            }
          }
          if (!targetWs) {
            const codebases = loadCodebases(codebasesPath)
            const wsSet = new Set(codebases.map(c => c.workspace).filter(w => w && w !== UNASSIGNED_WORKSPACE))
            if (wsSet.size === 1) {
              targetWs = [...wsSet][0]
            } else {
              const allInstWorkspaces = Object.values(instances).map(i => i.workspace).filter(Boolean)
              if (allInstWorkspaces.length === 1) {
                targetWs = allInstWorkspaces[0]
              }
            }
          }
          if (!targetWs) {
            sendJson(res, 400, { ok: false, error: 'Ambiguous primary codebase: please specify ?workspace=' })
            return
          }
          const inst = resolveInstance(instances, targetWs)
          if (!inst || !inst.port) {
            sendJson(res, 503, { ok: false, error: `No Vectr daemon registered for workspace ${targetWs}` })
            return
          }
          const host = inst.host || '127.0.0.1'
          const controller = new AbortController()
          const timer = setTimeout(() => controller.abort(), httpTimeoutMs)
          try {
            const probeRes = await fetch(`http://${host}:${inst.port}/v1/status`, { signal: controller.signal })
            if (!probeRes.ok) {
              sendJson(res, 503, { ok: false, error: `Primary daemon returned status ${probeRes.status}` })
              return
            }
            const statusData = await probeRes.json()
            sendJson(res, 200, { ok: true, status: statusData })
          } catch (err) {
            sendJson(res, 503, { ok: false, error: `Primary daemon probe failed: ${String(err)}` })
          } finally {
            clearTimeout(timer)
          }
          return
        }
        const entry = find()
        if (entry === undefined) {
          sendJson(res, 404, { ok: false, error: 'no such codebase' })
          return
        }
        // 问题1B: self-heal the tunnel before probing. A dead tunnel is reopened
        // (or yields a diagnostic 'tunnel down: ...' instead of a bare fetch
        // error) rather than silently reporting the persisted-but-false 'up'.
        const result = await testCodebase(entry, { deps, metaPath: codebasesPath, heal: true })
        sendJson(res, result.ok ? 200 : 503, result)
        return
      }
      if (req.method === 'POST' && (url.pathname.endsWith('/start') || url.pathname.endsWith('/start-daemon'))) {
        if (isSystemPrimarySlug(normSlug)) {
          const targetWs = url.searchParams.get('workspace')
          if (!targetWs) {
            sendJson(res, 400, { ok: false, error: 'Query parameter "workspace" required to start primary codebase daemon' })
            return
          }
          const handle = deps.spawnRunner('vectr', ['start', '--path', targetWs, ...startModeFlags(targetWs), '--json'])
          const startRes = await handle.promise
          if (startRes.signal !== null) {
            sendJson(res, 500, { ok: false, error: `vectr start for primary codebase was killed (${startRes.signal})` })
            return
          }
          if (startRes.code !== 0) {
            sendJson(res, 500, { ok: false, error: `vectr start failed for primary codebase: ${startRes.stderr}` })
            return
          }
          let parsed: { port?: number; [key: string]: unknown } = {}
          try {
            parsed = JSON.parse(startRes.stdout) as { port?: number }
          } catch (e) {
            sendJson(res, 500, { ok: false, error: `vectr start returned non-JSON: ${String(e)}` })
            return
          }
          sendJson(res, 200, { ok: true, slug: 'primary', localPort: parsed.port ?? 0 })
          return
        }
        const entry = find()
        if (entry === undefined) {
          sendJson(res, 404, { ok: false, error: 'no such codebase' })
          return
        }
        const result = await startCodebaseDaemon(deps, codebasesPath, entry)
        sendJson(res, result.ok ? 200 : 500, result)
        return
      }
      if (req.method === 'PATCH') {
        if (isSystemPrimarySlug(normSlug)) {
          sendJson(res, 403, { ok: false, error: 'Cannot reassign primary codebase of the workspace' })
          return
        }
        const entry = find()
        if (entry === undefined) {
          sendJson(res, 404, { ok: false, error: 'no such codebase' })
          return
        }
        let body: unknown
        try {
          body = await readJsonBody(req)
        } catch (error) {
          sendJson(res, 400, { error: String(error) })
          return
        }
        // Body shape: `{ workspace: string }` — the absolute target workspace.
        const { workspace } = (body ?? {}) as { workspace?: unknown }
        // PATCH accepts either an absolute workspace path (the normal assign
        // target) or the UNASSIGNED_WORKSPACE sentinel, which moves a codebase
        // back into the unassigned bucket without requiring a daemon registry
        // (consistent with GET / grouping semantics). Any other value is 400.
        const wsValid = typeof workspace === 'string' && workspace.length > 0 &&
          (workspace === UNASSIGNED_WORKSPACE || isAbsolute(workspace))
        if (!wsValid) {
          sendJson(res, 400, { error: 'PATCH body must include an absolute "workspace" path (or the "__unassigned__" sentinel)' })
          return
        }
        // Validate the target against the live daemon registry (assign only
        // moves a codebase to a real vectr workspace). A missing/unreadable
        // registry is a 500 (misconfiguration), not a silent pass.
        let instances: InstancesFile | undefined
        try {
          instances = readInstancesFile(ctx, instancesPath)
        } catch (error) {
          sendJson(res, 500, { error: String(error) })
          return
        }
        try {
          const updated = patchCodebase(
            codebasesPath,
            entry.slug,
            workspace,
            instances === undefined ? {} : { instances },
          )
          sendJson(res, 200, { ok: true, ...stripSecret(updated) })
        } catch (error) {
          if (error instanceof CodebaseError) {
            sendJson(res, error.status, { ok: false, error: error.message })
          } else {
            sendJson(res, 500, { ok: false, error: String(error) })
          }
        }
        return
      }
      sendJson(res, 405, { error: 'method not allowed' })
    },
  }), 'vectr-client: /api/vectr/codebases/:slug')
}
